#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;

    while (scanf("%d%d", &n, &k) == 2) {
        vector<int> p(n);
        vector<long long> costs(n);
        vector<int> allP;
        vector<long long> allCosts;
        vector<vector<long long>> groups(n + 2);

        allP.reserve(n);
        allCosts.reserve(n);

        for (int i = 0; i < n; ++i) {
            int e;
            scanf("%d%d", &p[i], &e);
            costs[i] = e;
            allP.push_back(p[i]);
            allCosts.push_back(costs[i]);

            if (-1 <= p[i] && p[i] <= n)
                groups[p[i] + 1].push_back(costs[i]);
        }

        sort(allP.begin(), allP.end());
        sort(allCosts.begin(), allCosts.end());
        for (auto &group : groups)
            sort(group.begin(), group.end());

        vector<long long> values;
        vector<int> globalCount;
        vector<long long> globalSum;

        for (int i = 0; i < n;) {
            int j = i;
            long long sum = 0;
            while (j < n && allCosts[j] == allCosts[i]) {
                sum += allCosts[j];
                ++j;
            }

            values.push_back(allCosts[i]);
            globalCount.push_back((globalCount.empty() ? 0 : globalCount.back()) + (j - i));
            globalSum.push_back((globalSum.empty() ? 0LL : globalSum.back()) + sum);
            i = j;
        }

        const long long INF = 6000000000000000000LL;
        long long answer = INF;

        for (int bribed = 0; bribed <= n; ++bribed) {
            int initialAhead =
                n - int(lower_bound(allP.begin(), allP.end(), bribed - 1) - allP.begin());

            int required = max(0, initialAhead - (k - 1));
            if (required > bribed)
                continue;

            const auto &a = groups[bribed];
            const auto &b = groups[bribed + 1];

            vector<long long> removable;
            removable.reserve(a.size() + b.size());
            merge(a.begin(), a.end(), b.begin(), b.end(), back_inserter(removable));

            if (required > static_cast<int>(removable.size()))
                continue;

            vector<long long> removablePrefix(removable.size() + 1, 0);
            for (size_t i = 0; i < removable.size(); ++i)
                removablePrefix[i + 1] = removablePrefix[i] + removable[i];

            long long current = removablePrefix[required];
            int remaining = bribed - required;

            if (remaining > n - required)
                continue;

            if (remaining > 0) {
                int left = 0;
                int right = static_cast<int>(values.size()) - 1;

                while (left < right) {
                    int mid = left + (right - left) / 2;
                    long long value = values[mid];

                    int selectedNotGreater = int(
                        upper_bound(removable.begin(),
                                    removable.begin() + required,
                                    value) - removable.begin());

                    int available = globalCount[mid] - selectedNotGreater;

                    if (available >= remaining)
                        right = mid;
                    else
                        left = mid + 1;
                }

                long long threshold = values[left];

                int globalLessCount = (left == 0 ? 0 : globalCount[left - 1]);
                long long globalLessSum = (left == 0 ? 0LL : globalSum[left - 1]);

                int selectedLessCount = int(
                    lower_bound(removable.begin(),
                                removable.begin() + required,
                                threshold) - removable.begin());
                long long selectedLessSum = removablePrefix[selectedLessCount];

                int availableLessCount = globalLessCount - selectedLessCount;
                long long availableLessSum = globalLessSum - selectedLessSum;

                current += availableLessSum;
                current += 1LL * (remaining - availableLessCount) * threshold;
            }

            answer = min(answer, current);
        }

        if (answer == INF)
            printf("-1\n");
        else
            printf("%lld\n", answer);
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class Fenwick {
    int n;
    vector<int> count;
    vector<long long> sum;
    const vector<long long>* values;

public:
    Fenwick() : n(0), values(nullptr) {}

    Fenwick(int size, const vector<long long>& compressed)
        : n(size), count(n + 1, 0), sum(n + 1, 0), values(&compressed) {}

    void add(int index, int countDelta, long long sumDelta) {
        for (++index; index <= n; index += index & -index) {
            count[index] += countDelta;
            sum[index] += sumDelta;
        }
    }

    int totalCount() const {
        int result = 0;
        for (int i = n; i > 0; i -= i & -i)
            result += count[i];
        return result;
    }

    int kthIndex(int k) const {
        int index = 0;
        int accumulated = 0;

        int step = 1;
        while ((step << 1) <= n) step <<= 1;

        for (; step; step >>= 1) {
            int next = index + step;
            if (next <= n && accumulated + count[next] < k) {
                index = next;
                accumulated += count[next];
            }
        }
        return index;
    }

    long long kthValue(int k) const {
        return (*values)[kthIndex(k)];
    }

    long long sumSmallest(int k) const {
        if (k <= 0) return 0;

        int index = 0;
        int accumulatedCount = 0;
        long long accumulatedSum = 0;

        int step = 1;
        while ((step << 1) <= n) step <<= 1;

        for (; step; step >>= 1) {
            int next = index + step;
            if (next <= n && accumulatedCount + count[next] < k) {
                index = next;
                accumulatedCount += count[next];
                accumulatedSum += sum[next];
            }
        }

        return accumulatedSum +
               1LL * (k - accumulatedCount) * (*values)[index];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;

    while (cin >> n >> k) {
        vector<int> p(n);
        vector<long long> e(n);
        vector<long long> coordinates;
        coordinates.reserve(n);

        for (int i = 0; i < n; ++i) {
            cin >> p[i] >> e[i];
            coordinates.push_back(e[i]);
        }

        sort(coordinates.begin(), coordinates.end());
        coordinates.erase(unique(coordinates.begin(), coordinates.end()),
                          coordinates.end());

        vector<int> costIndex(n);
        for (int i = 0; i < n; ++i) {
            costIndex[i] = lower_bound(coordinates.begin(), coordinates.end(),
                                       e[i]) - coordinates.begin();
        }

        vector<long long> sortedCosts = e;
        sort(sortedCosts.begin(), sortedCosts.end());

        vector<long long> globalPrefix(n + 1, 0);
        for (int i = 0; i < n; ++i)
            globalPrefix[i + 1] = globalPrefix[i] + sortedCosts[i];

        vector<int> sortedP = p;
        sort(sortedP.begin(), sortedP.end());

        vector<vector<int>> groups(n + 2);
        for (int i = 0; i < n; ++i) {
            if (-1 <= p[i] && p[i] <= n)
                groups[p[i] + 1].push_back(i);
        }

        Fenwick beneficial((int)coordinates.size(), coordinates);
        Fenwick outside((int)coordinates.size(), coordinates);

        for (int i = 0; i < n; ++i) {
            if (p[i] == -1 || p[i] == 0)
                beneficial.add(costIndex[i], 1, e[i]);
            else
                outside.add(costIndex[i], 1, e[i]);
        }

        const long long INF = numeric_limits<long long>::max() / 4;
        long long answer = INF;

        for (int selected = 0; selected <= n; ++selected) {
            int aheadWithoutUsefulSelections =
                sortedP.end() -
                lower_bound(sortedP.begin(), sortedP.end(), selected - 1);

            int required = aheadWithoutUsefulSelections - (k - 1);

            if (required <= 0) {
                answer = min(answer, globalPrefix[selected]);
            } else if (required <= selected &&
                       required <= beneficial.totalCount()) {
                int outsideNeeded = selected - required;

                if (outsideNeeded <= outside.totalCount()) {
                    bool unconstrainedIsFeasible =
                        outsideNeeded == outside.totalCount() ||
                        beneficial.kthValue(required) <=
                            outside.kthValue(outsideNeeded + 1);

                    long long cost;
                    if (unconstrainedIsFeasible) {
                        cost = globalPrefix[selected];
                    } else {
                        cost = beneficial.sumSmallest(required) +
                               outside.sumSmallest(outsideNeeded);
                    }

                    answer = min(answer, cost);
                }
            }

            if (selected == n) break;

            int leavingValue = selected - 1;
            if (-1 <= leavingValue && leavingValue <= n) {
                for (int index : groups[leavingValue + 1]) {
                    beneficial.add(costIndex[index], -1, -e[index]);
                    outside.add(costIndex[index], 1, e[index]);
                }
            }

            int enteringValue = selected + 1;
            if (-1 <= enteringValue && enteringValue <= n) {
                for (int index : groups[enteringValue + 1]) {
                    outside.add(costIndex[index], -1, -e[index]);
                    beneficial.add(costIndex[index], 1, e[index]);
                }
            }
        }

        if (answer == INF)
            cout << -1 << '\n';
        else
            cout << answer << '\n';
    }

    return 0;
}

